// Хариу бүрийг JSON болгож буцаах жижиг туслах.
function json(body, status) {
  return new Response(JSON.stringify(body), {
    status: status || 200,
    headers: { "Content-Type": "application/json" },
  });
}

async function handleRequest(request) {
  const path = new URL(request.url).pathname;

  // энд бичнэ үү

  return json({ error: "Хаяг олдсонгүй: " + path }, 404);
}

window.handleRequest = handleRequest;

// «API турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
// Token бүр аль хэрэглэгчийнх болохыг db.sessions заана (нэвтрэлт нь m12-l2).

const db = {
  users: [
    { id: 1, name: "Админ", email: "admin@shop.mn", role: "admin" },
    { id: 2, name: "Болд", email: "bold@shop.mn", role: "user" },
  ],
  orders: [
    { id: 1, userId: 2, items: [{ id: 1, quantity: 1 }] },
    { id: 2, userId: 2, items: [{ id: 2, quantity: 3 }] },
  ],
  sessions: { "tok-admin": 1, "tok-user": 2 },
};

window.db = db;

const SCENARIOS = [
  { key: "noToken", label: "Token байхгүй", method: "GET", path: "/api/admin/orders" },
  { key: "asUser", label: "Энгийн хэрэглэгч", method: "GET", path: "/api/admin/orders", token: "tok-user" },
  { key: "asAdmin", label: "Админ", method: "GET", path: "/api/admin/orders", token: "tok-admin" },
];

const output = document.getElementById("output");

function render(scenario, status, body, error, sentToken) {
  const box = document.createElement("section");
  box.className = "call";
  box.dataset.testid = "call-" + scenario.key;

  const head = document.createElement("h2");
  const badge = document.createElement("span");
  badge.className = "status " + (error ? "s-err" : "s-" + String(status)[0] + "xx");
  badge.dataset.testid = "status-" + scenario.key;
  badge.textContent = error ? "алдаа" : String(status);
  head.append(badge, document.createTextNode(" " + scenario.method + " " + scenario.path));
  if (sentToken) {
    const lock = document.createElement("span");
    lock.className = "lock";
    lock.textContent = "🔑 token-той";
    head.append(lock);
  }
  box.append(head);

  const label = document.createElement("p");
  label.className = "muted";
  label.textContent = scenario.label;
  box.append(label);

  const pre = document.createElement("pre");
  pre.dataset.testid = "body-" + scenario.key;
  pre.textContent = error ? error : JSON.stringify(body, null, 2);
  box.append(pre);

  output.append(box);
}

(async function () {
  window.RESULTS = {};

  for (const scenario of SCENARIOS) {
    const headers = {};
    const init = { method: scenario.method };
    if (scenario.body !== undefined) {
      headers["Content-Type"] = "application/json";
      init.body = JSON.stringify(scenario.body);
    }
    const sendToken = typeof scenario.token === "string";
    if (sendToken) headers.Authorization = "Bearer " + scenario.token;
    init.headers = headers;

    let status = 0;
    let body = null;
    let error = null;

    try {
      const response = await handleRequest(new Request("https://shop.mn" + scenario.path, init));
      if (!(response instanceof Response)) {
        throw new Error("handleRequest нь Response биш зүйл буцаалаа");
      }
      status = response.status;
      const text = await response.text();
      try {
        body = text ? JSON.parse(text) : null;
      } catch (problem) {
        body = text;
      }
    } catch (problem) {
      error = problem.message;
    }

    window.RESULTS[scenario.key] = { status, body, error };
    render(scenario, status, body, error, sendToken);
  }

  document.body.dataset.ready = "1";
})();

