// Shop.mn-ий сервер — эрхийн хяналт (role).

function json(body, status) {
  return new Response(JSON.stringify(body), {
    status: status || 200,
    headers: { "Content-Type": "application/json" },
  });
}

// Authorization толгойгоос token-ыг салгаж, аль хэрэглэгч болохыг олно.
function currentUser(request) {
  const auth = request.headers.get("Authorization") || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7) : null;
  const userId = token ? db.sessions[token] : undefined;
  return userId ? db.users.find((u) => u.id === userId) : null;
}

async function handleRequest(request) {
  const path = new URL(request.url).pathname;

  if (path === "/api/admin/orders" && request.method === "GET") {
    const user = currentUser(request);
    if (!user) {
      return json({ error: "Нэвтрээгүй байна" }, 401);
    }
    if (user.role !== "admin") {
      return json({ error: "Танд энэ үйлдлийн эрх алга" }, 403);
    }
    return json(db.orders);
  }

  return json({ error: "Хаяг олдсонгүй: " + path }, 404);
}

window.handleRequest = handleRequest;
